"""Plain-language reference for every detector: what it tests, why the anomaly matters, how to read the result.

The report shows these next to each detector result and each finding's signals, together with a sentence
that interprets the specific result (severity, threshold, peer position). Keep entries short and neutral:
they explain a test, they never allege wrongdoing.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Explainer:
    what: str  # what the detector measures
    why: str  # why this anomaly matters
    read: str  # how to interpret the value, and common innocent explanations


E = Explainer

