def definition(detector_id: str) -> str:
    """How a test computes its result and reference value (its docstring), for the investigation and the auditor,
    so neither has to guess how a figure was built."""
    from ffi.detectors.base import REGISTRY

    spec = REGISTRY.get(detector_id)
    doc = " ".join((spec.fn.__doc__ or "").split()) if spec else ""
    ex = explain(detector_id)
    return " ".join(x for x in (doc, ex.what if ex and ex.what not in doc else "") if x)


def explain(detector_id: str) -> Explainer | None:
    return CATALOG.get(detector_id)


def interpret(status: str, severity: float | None, flag_at: float, flagged: bool = False, pct_peer: float | None = None,
              suppressed_by: str | None = None, reason: str = "") -> str:
    """One sentence that interprets this specific result."""
    if status == "n/a":
        return reason or "Not run: the test's inputs mean something different for this type of company."
    if status == "skipped":
        return f"Not run: {reason.rstrip('.')}." if reason else "Not run: required data was not available."
    if status == "error":
        return "The detector failed on this company's data; the failure is reported rather than hidden."
    if suppressed_by:
        return f"Raised but suppressed: {suppressed_by}. It does not count towards the risk index."
    sev = severity or 0.0
    peer = (f" The company sits at the {_ordinal(round(pct_peer))} percentile of its peers." if pct_peer is not None else "")
    if flagged and sev >= max(0.8, flag_at):
        band = f"Strong signal (severity {sev:.2f}, flagged at {flag_at:.2f}). It counts towards the risk index and is a priority for follow-up."
    elif flagged:
        band = f"Flagged (severity {sev:.2f}, threshold {flag_at:.2f}). It counts towards the risk index; check the innocent explanations first."
    elif sev >= 0.3:
        band = f"Notable but below the flag threshold (severity {sev:.2f} vs {flag_at:.2f}). Worth knowing; not counted as a finding on its own."
    elif sev > 0:
        band = f"Weak signal (severity {sev:.2f}); within the normal range."
    else:
        band = "No concern: the result is within the expected range."
    return band + peer


def _ordinal(n: int) -> str:
    suffix = "th" if 10 <= n % 100 <= 20 else {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"
